  "inlineSchema": "// Prisma Client este codul generat automat de Prisma,\n// prin care backendul vorbește cu baza de date.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Statusurile posibile pentru articolele de blog.\nenum BlogStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\n// Statusurile pentru cererile primite prin formular.\nenum ContactStatus {\n  NEW\n  READ\n  REPLIED\n  ARCHIVED\n}\n\n// Tipurile de evenimente pentru analytics.\nenum AnalyticsEventType {\n  PAGE_VIEW\n  BLOG_VIEW\n  SCROLL_DEPTH\n  TIME_ON_PAGE\n  CTA_CLICK\n  PRICING_VIEW\n  PRICING_CLICK\n  CONTACT_OPEN\n  CONTACT_START\n  CONTACT_SUBMIT\n  CONTACT_SUCCESS\n  CONTACT_ERROR\n  OUTBOUND_CLICK\n  ERROR\n}\n\n// Roluri pentru viitorul dashboard de admin.\nenum AdminRole {\n  OWNER\n  ADMIN\n  EDITOR\n}\n\n// Utilizator admin pentru viitor.\n// Nu îl folosim încă, dar pregătim baza pentru dashboard.\nmodel AdminUser {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  passwordHash String\n  role         AdminRole @default(ADMIN)\n  active       Boolean   @default(true)\n\n  lastLoginAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n\nmodel AdminAuditLog {\n  id        String   @id @default(cuid())\n  adminId   String?\n  action    String\n  entity    String?\n  entityId  String?\n  metadata  Json?\n  ipHash    String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([adminId])\n  @@index([action])\n  @@index([entity])\n  @@index([createdAt])\n}\n\n// Articolele de blog.\n// În loc să ai articolele hardcodate în JS,\n// le ținem în baza de date.\nmodel BlogPost {\n  id              String     @id @default(cuid())\n  title           String\n  slug            String     @unique\n  excerpt         String?\n  content         String\n  coverImage      String?\n  status          BlogStatus @default(DRAFT)\n  featured        Boolean    @default(false)\n  readingMinutes  Int?\n  metaTitle       String?\n  metaDescription String?\n  publishedAt     DateTime?\n\n  categoryId String?\n  category   BlogCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  tags BlogPostTag[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([publishedAt])\n  @@index([featured])\n}\n\n// Categorii pentru blog.\n// Exemplu: Web Design, SEO, UX, Business etc.\nmodel BlogCategory {\n  id          String  @id @default(cuid())\n  name        String\n  slug        String  @unique\n  description String?\n\n  posts BlogPost[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Taguri pentru blog.\n// Exemplu: conversie, website, responsive, branding etc.\nmodel BlogTag {\n  id   String @id @default(cuid())\n  name String\n  slug String @unique\n\n  posts BlogPostTag[]\n\n  createdAt DateTime @default(now())\n}\n\n// Tabel de legătură între articole și taguri.\n// Un articol poate avea mai multe taguri,\n// iar un tag poate aparține mai multor articole.\nmodel BlogPostTag {\n  postId String\n  tagId  String\n\n  post BlogPost @relation(fields: [postId], references: [id], onDelete: Cascade)\n  tag  BlogTag  @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([postId, tagId])\n}\n\n// Cererile primite prin formularul din ContactDrawer.\n// Aici stocăm date personale, separate de analytics.\nmodel ContactSubmission {\n  id           String        @id @default(cuid())\n  name         String\n  email        String\n  phone        String?\n  selectedPlan String?\n  message      String\n  gdprAccepted Boolean       @default(false)\n  status       ContactStatus @default(NEW)\n\n  // Contextul paginii de unde a venit cererea.\n  sourcePage String?\n  userAgent  String?\n  ipAddress  String?\n\n  // Legătură opțională cu sesiunea anonimă de analytics.\n  // Important: analytics nu conține nume/email/telefon.\n  sessionId String?\n\n  // UTM-uri pentru campanii.\n  // Exemplu: Instagram, Google Ads, TikTok, newsletter etc.\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmContent  String?\n  utmTerm     String?\n\n  // Dacă utilizatorul a acceptat tracking analytics.\n  consentAnalytics Boolean @default(false)\n\n  // Status email.\n  emailSent  Boolean @default(false)\n  emailError String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([createdAt])\n  @@index([email])\n  @@index([sessionId])\n  @@index([utmSource])\n  @@index([utmCampaign])\n}\n\n// Sesiune anonimă de analytics.\n// Nu salvăm nume, email, telefon sau mesaj aici.\nmodel AnalyticsSession {\n  id        String @id @default(cuid())\n  sessionId String @unique\n\n  // Consimțământ pentru analytics avansat.\n  consentAnalytics Boolean @default(false)\n\n  // Prima și ultima pagină văzută în sesiune.\n  firstPath String?\n  lastPath  String?\n\n  // Referrer și UTM-uri.\n  referrer String?\n\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmContent  String?\n  utmTerm     String?\n\n  // Informații generale, non-personale/pseudonimizate.\n  deviceType    String?\n  browser       String?\n  ipHash        String?\n  userAgentHash String?\n\n  startedAt   DateTime  @default(now())\n  lastSeenAt  DateTime  @default(now())\n  convertedAt DateTime?\n\n  events AnalyticsEvent[]\n\n  @@index([startedAt])\n  @@index([lastSeenAt])\n  @@index([convertedAt])\n  @@index([utmSource])\n  @@index([utmCampaign])\n}\n\n// Evenimente pentru analytics.\n// Exemplu: page view, click pe CTA, deschidere formular, submit formular.\n// Metadata trebuie folosită doar pentru detalii non-personale.\nmodel AnalyticsEvent {\n  id        String             @id @default(cuid())\n  sessionId String\n  type      AnalyticsEventType\n\n  path  String?\n  label String?\n  value String?\n\n  metadata Json?\n\n  createdAt DateTime @default(now())\n\n  session AnalyticsSession @relation(fields: [sessionId], references: [sessionId], onDelete: Cascade)\n\n  @@index([sessionId])\n  @@index([type])\n  @@index([path])\n  @@index([createdAt])\n}\n\n// Proiectele din portofoliu.\n// Mai târziu putem muta portofoliul din JS în DB.\nmodel PortfolioProject {\n  id          String  @id @default(cuid())\n  title       String\n  slug        String  @unique\n  category    String?\n  description String\n  image       String?\n  url         String?\n  featured    Boolean @default(false)\n  order       Int     @default(0)\n  published   Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([published])\n  @@index([featured])\n  @@index([order])\n}\n\n// Texte modificabile din site.\n// Exemplu: hero.title, footer.description, cta.text etc.\nmodel SiteText {\n  id    String  @id @default(cuid())\n  key   String  @unique\n  value String\n  group String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([group])\n}\n\n// Setări firmă.\n// Exemplu: email, telefon, adresă, CUI, social links etc.\nmodel CompanySetting {\n  id    String @id @default(cuid())\n  key   String @unique\n  value String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// Imagini/media folosite în blog, portofoliu etc.\nmodel MediaAsset {\n  id   String  @id @default(cuid())\n  url  String\n  alt  String?\n  type String?\n\n  createdAt DateTime @default(now())\n}\n",
